"""Local, dependency-free visual system shared by the guided editors."""

EDITOR_CSS = '''
:root{--ink:#203b37;--muted:#647772;--line:#dce5e0;--green:#16735d;--soft:#edf5f0}
*{box-sizing:border-box}html,body{overflow-x:hidden}body{font:15px/1.5 "Segoe UI",Arial,sans-serif!important;color:var(--ink)!important;background:#f6f8f5!important;margin:0!important;padding:20px!important}
main,.container{width:100%!important;max-width:1360px!important;margin:0 auto!important;padding:0!important}
h1{font-size:26px!important;letter-spacing:-.7px}h2{font-size:19px!important;letter-spacing:-.3px}h3{font-size:16px}p{line-height:1.6}small,.hint,.legend{color:var(--muted)}
button,.button{font:600 14px/1.3 "Segoe UI",Arial,sans-serif!important;padding:11px 16px!important;border:1px solid var(--line)!important;border-radius:9px!important;background:white!important;color:var(--ink)!important;cursor:pointer;text-decoration:none!important;box-shadow:none!important}button:hover,.button:hover{background:var(--soft)!important;border-color:#9dbbb0!important}button:disabled{opacity:.45;cursor:default}button.primary,button.active{background:var(--green)!important;color:white!important;border-color:var(--green)!important}button.danger{color:#a54133!important}
button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #75bca5!important;outline-offset:3px}a{color:var(--green)!important}input,select{font:inherit!important;border:1px solid #c8d6cf!important;border-radius:8px!important;padding:10px 12px!important;background:white;color:var(--ink);max-width:100%;min-width:0}input[type=checkbox]{accent-color:var(--green);width:17px;height:17px;vertical-align:middle;padding:0!important}label{line-height:1.7}
.card,.panel,section{border:1px solid var(--line)!important;border-radius:14px!important;box-shadow:none!important;background:#fff!important;padding:22px!important}.bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0!important}
.status,#status,.msg{border:0!important;background:var(--soft)!important;border-radius:10px!important;padding:12px 16px!important;font-size:14px!important;white-space:pre-wrap}.msg:empty,#msg:empty{display:none}.warn{background:#fff4df!important;color:#855321!important}.ok{color:var(--green)!important}
table{width:100%!important;min-width:0!important;border-collapse:collapse}td,th{text-align:left;padding:14px!important;border-bottom:1px solid var(--line)!important;overflow-wrap:anywhere;vertical-align:top}th{color:var(--muted);font-size:12px;letter-spacing:.3px;font-weight:600;background:#f6f8f5!important}td input{max-width:100%}details{border-top:1px solid var(--line);padding-top:12px;margin-top:16px}summary{cursor:pointer;color:var(--ink)!important;font-weight:600;padding:8px 0}
pre{font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%;border-radius:10px}.layout>*{min-width:0}#wrap{border:1px solid var(--line)!important;border-radius:12px;overflow:visible!important;max-height:none!important;background:#fff}#canvas{width:100%;height:auto;max-width:100%}.scroll,.tabela-wrapper{overflow:visible!important}.model-editor{max-width:none!important;min-width:0!important}.modelo-ocr{max-width:100%!important}#state{font-size:12px;padding:6px 10px;border-radius:20px}#pins{display:inline-flex;gap:6px;flex-wrap:wrap}#pins button{min-width:44px}
.parameter-source{font-size:13px!important;color:var(--muted)!important;margin:8px 0}.parameter-source details{margin:6px 0;font-size:12px;border:0;padding:0}.parameter-source summary{font-size:12px;font-weight:400;padding:0;color:var(--muted)!important}.model-notices{margin:12px 0;font-size:13px}.model-editor>small{font-size:12px;margin:6px 0 18px;color:#8a6729}.model-editor>details{border:1px solid var(--line);border-radius:10px;padding:6px 16px;background:#fafcf9}.model-editor>details>div:not(.model-notices){border-color:var(--line)!important}.model-editor input:not([type=checkbox]){width:100%!important;max-width:100%!important}.model-editor label{font-size:14px}.model-editor label:has(input[type=checkbox]){display:flex;align-items:flex-start;gap:8px;font-size:12px;color:var(--muted);margin-top:8px}.model-editor label input[type=checkbox]{flex:none}
[hidden]{display:none!important}.guided-editor main>h1,.guided-editor main>a#back,.guided-editor>h2,.guided-editor>h2+.hint,.guided-editor main>h1+p{display:none!important}.guided-editor>p.hint:last-of-type{display:none!important}.guided-editor main>.bar:empty{display:none!important}
@media(max-width:700px){body{padding:12px!important}.card,.panel,section{padding:16px!important}.layout{grid-template-columns:1fr!important}table,tbody,tr,td{display:block}thead{display:none}tr{border:1px solid var(--line);border-radius:10px;padding:10px;margin:12px 0}td{padding:8px!important}td[data-label]::before{content:attr(data-label);display:block;font-size:12px;color:var(--muted);margin-bottom:4px}.pin input{width:100%!important}}
'''
